    return "import { useSignIn } from \"@clerk/expo\";\nimport { type Href, Link, useRouter } from \"expo-router\";\nimport React from \"react\";\nimport { Pressable, StyleSheet, Text, TextInput, View } from \"react-native\";\n\nfunction pushDecoratedUrl(router: ReturnType<typeof useRouter>, decorateUrl: (url: string) => string, href: string) {\n  const url = decorateUrl(href);\n  const nextHref = url.startsWith(\"http\") ? new URL(url).pathname : url;\n  router.push(nextHref as Href);\n}\n\nexport default function Page() {\n  const { signIn, errors, fetchStatus } = useSignIn();\n  const router = useRouter();\n  const [emailAddress, setEmailAddress] = React.useState(\"\");\n  const [password, setPassword] = React.useState(\"\");\n  const [code, setCode] = React.useState(\"\");\n  const [statusMessage, setStatusMessage] = React.useState<string | null>(null);\n\n  const emailCodeFactor = signIn.supportedSecondFactors.find(\n    (factor) => factor.strategy === \"email_code\",\n  );\n  const requiresEmailCode =\n    signIn.status === \"needs_client_trust\" ||\n    (signIn.status === \"needs_second_factor\" && !!emailCodeFactor);\n\n  const handleSubmit = async () => {\n    setStatusMessage(null);\n\n    const { error } = await signIn.password({\n      emailAddress,\n      password,\n    });\n\n    if (error) {\n      console.error(JSON.stringify(error, null, 2));\n      setStatusMessage(error.longMessage ?? \"Unable to sign in. Please try again.\");\n      return;\n    }\n\n    if (signIn.status === \"complete\") {\n      await signIn.finalize({\n        navigate: ({ session, decorateUrl }) => {\n          if (session?.currentTask) {\n            console.log(session.currentTask);\n            return;\n          }\n\n          pushDecoratedUrl(router, decorateUrl, \"/\");\n        },\n      });\n    } else if (signIn.status === \"needs_second_factor\" || signIn.status === \"needs_client_trust\") {\n      if (emailCodeFactor) {\n        await signIn.mfa.sendEmailCode();\n        setStatusMessage(`We sent a verification code to ${emailCodeFactor.safeIdentifier}.`);\n      } else {\n        console.error(\"Second factor is required, but email_code is not available:\", signIn);\n        setStatusMessage(\"A second factor is required, but this screen only supports email codes right now.\");\n      }\n    } else {\n      console.error(\"Sign-in attempt not complete:\", signIn);\n      setStatusMessage(\"Sign-in could not be completed. Check the logs for more details.\");\n    }\n  };\n\n  const handleVerify = async () => {\n    setStatusMessage(null);\n\n    await signIn.mfa.verifyEmailCode({ code });\n\n    if (signIn.status === \"complete\") {\n      await signIn.finalize({\n        navigate: ({ session, decorateUrl }) => {\n          if (session?.currentTask) {\n            console.log(session.currentTask);\n            return;\n          }\n\n          pushDecoratedUrl(router, decorateUrl, \"/\");\n        },\n      });\n    } else {\n      console.error(\"Sign-in attempt not complete:\", signIn);\n      setStatusMessage(\"That code did not complete sign-in. Please try again.\");\n    }\n  };\n\n  if (requiresEmailCode) {\n    return (\n      <View style={styles.container}>\n        <Text style={styles.title}>Verify your account</Text>\n        {statusMessage && <Text style={styles.helper}>{statusMessage}</Text>}\n        <TextInput\n          style={styles.input}\n          value={code}\n          placeholder=\"Enter your verification code\"\n          placeholderTextColor=\"#666666\"\n          onChangeText={(value) => setCode(value)}\n          keyboardType=\"numeric\"\n        />\n        {errors.fields.code && <Text style={styles.error}>{errors.fields.code.message}</Text>}\n        <Pressable\n          style={({ pressed }) => [\n            styles.button,\n            fetchStatus === \"fetching\" && styles.buttonDisabled,\n            pressed && styles.buttonPressed,\n          ]}\n          onPress={handleVerify}\n          disabled={fetchStatus === \"fetching\"}\n        >\n          <Text style={styles.buttonText}>Verify</Text>\n        </Pressable>\n        <Pressable\n          style={({ pressed }) => [styles.secondaryButton, pressed && styles.buttonPressed]}\n          onPress={() => signIn.mfa.sendEmailCode()}\n        >\n          <Text style={styles.secondaryButtonText}>I need a new code</Text>\n        </Pressable>\n      </View>\n    );\n  }\n\n  return (\n    <View style={styles.container}>\n      <Text style={styles.title}>Sign in</Text>\n      {statusMessage && <Text style={styles.helper}>{statusMessage}</Text>}\n      <Text style={styles.label}>Email address</Text>\n      <TextInput\n        style={styles.input}\n        autoCapitalize=\"none\"\n        value={emailAddress}\n        placeholder=\"Enter email\"\n        placeholderTextColor=\"#666666\"\n        onChangeText={(value) => setEmailAddress(value)}\n        keyboardType=\"email-address\"\n      />\n      {errors.fields.identifier && <Text style={styles.error}>{errors.fields.identifier.message}</Text>}\n      <Text style={styles.label}>Password</Text>\n      <TextInput\n        style={styles.input}\n        value={password}\n        placeholder=\"Enter password\"\n        placeholderTextColor=\"#666666\"\n        secureTextEntry={true}\n        onChangeText={(value) => setPassword(value)}\n      />\n      {errors.fields.password && <Text style={styles.error}>{errors.fields.password.message}</Text>}\n      <Pressable\n        style={({ pressed }) => [\n          styles.button,\n          (!emailAddress || !password || fetchStatus === \"fetching\") && styles.buttonDisabled,\n          pressed && styles.buttonPressed,\n        ]}\n        onPress={handleSubmit}\n        disabled={!emailAddress || !password || fetchStatus === \"fetching\"}\n      >\n        <Text style={styles.buttonText}>Sign in</Text>\n      </Pressable>\n      <View style={styles.linkContainer}>\n        <Text>Don't have an account? </Text>\n        <Link href=\"/sign-up\">\n          <Text style={styles.linkText}>Sign up</Text>\n        </Link>\n      </View>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: {\n    flex: 1,\n    padding: 20,\n    gap: 12,\n  },\n  title: {\n    marginBottom: 8,\n    fontSize: 24,\n    fontWeight: \"700\",\n  },\n  label: {\n    fontWeight: \"600\",\n    fontSize: 14,\n  },\n  input: {\n    borderWidth: 1,\n    borderColor: \"#ccc\",\n    borderRadius: 8,\n    padding: 12,\n    fontSize: 16,\n    backgroundColor: \"#fff\",\n  },\n  button: {\n    backgroundColor: \"#0a7ea4\",\n    paddingVertical: 12,\n    paddingHorizontal: 24,\n    borderRadius: 8,\n    alignItems: \"center\",\n    marginTop: 8,\n  },\n  buttonPressed: {\n    opacity: 0.7,\n  },\n  buttonDisabled: {\n    opacity: 0.5,\n  },\n  buttonText: {\n    color: \"#fff\",\n    fontWeight: \"600\",\n  },\n  secondaryButton: {\n    paddingVertical: 12,\n    paddingHorizontal: 24,\n    borderRadius: 8,\n    alignItems: \"center\",\n    marginTop: 8,\n  },\n  secondaryButtonText: {\n    color: \"#0a7ea4\",\n    fontWeight: \"600\",\n  },\n  linkContainer: {\n    flexDirection: \"row\",\n    gap: 4,\n    marginTop: 12,\n    alignItems: \"center\",\n  },\n  linkText: {\n    color: \"#0a7ea4\",\n    fontWeight: \"600\",\n  },\n  error: {\n    color: \"#d32f2f\",\n    fontSize: 12,\n    marginTop: -8,\n  },\n  helper: {\n    color: \"#555555\",\n    fontSize: 13,\n  },\n});\n";
